use xiom.io;

use xiom.string;
type PositiveInt = {
  value: Int;
  invariant: value > 0;
}

type NonEmptyVec[T] = {
  data: Vec[T];
  invariant: data.len() > 0;
}

type ValidEmail = {
  address: Str;
  invariant: string.str_index_of(address, "@") != None;
  invariant: string.str_index_of(address, ".") != None;
}

type ValidPhone = {
  number: Str;
  invariant: string.str_len(number) >= 10;
  invariant: string.str_len(number) <= 15;
}

fn contact(user_email: &ValidEmail, user_phone: &ValidPhone) {
  io.println("Email: " + user_email.address.to_str());
  io.println("Phone: " + user_phone.number.to_str());
}

fn main() -> Int {
  let email: ValidEmail = ValidEmail{ address: "user@example.com" };
  let phone: ValidPhone = ValidPhone{ number: "1234567890" };
  contact(&email, &phone);
  return 0;
}
